from lib import *
S = SS('u163')
R = J('u163'); sl = R['slow']
steps = [
    step("释放后使用:v 被 drop 之后,裸指针 p 仍被读出。普通编译运行退出码 0、打印 2(既不是 1 也没有报错,读到的是已释放内存里的东西);Miri 运行退出码 1,报「alloc290 has been freed, so this pointer is dangling」,并把三处位置都指出来:使用在 5:29、分配在 2:13(vec![1, 2, 3])、释放在 4:5(drop(v))。", t=tl(S(1)), mark=lidx(S(1), 'Undefined Behavior', 'was allocated here', 'was deallocated here'), done=lidx(S(1), '退出码 0', '    2'), kv=KV([['普通运行', '退出码 0,打印 2'], ['Miri', '退出码 1,指出分配/释放/使用']], ['Miri'])),
    step("越界读取:读 3 个元素的 Vec 之外的第 4 个 u32。普通运行退出码 0、打印 0;Miri 指出「attempting to access 4 bytes, but got alloc+0xc which is at or beyond the end of the allocation of size 12 bytes」—— 分配大小 12 字节,访问的偏移正好是 0xc = 12。", t=tl(S(2)), mark=lidx(S(2), 'attempting to access'), done=lidx(S(2), '退出码 0'), kv=KV([['普通运行', '退出码 0,打印 0'], ['Miri', '12 字节分配,在偏移 0xc 访问']], ['Miri'])),
    step("未初始化与非法值:对 u32 做 MaybeUninit::uninit().assume_init(),普通运行打印 72861972(随机的垃圾值),编译器自己就已经给出 invalid_value 警告;Miri 报「encountered uninitialized memory, but expected an integer」。把 2 transmute 成 bool,普通运行打印 false,Miri 报「encountered 0x02, but expected a boolean」。", t=tl(S(3)), mark=lidx(S(3), 'encountered uninitialized', 'encountered 0x02'), done=lidx(S(3), '72861972', 'false'), kv=KV([['uninit u32', '普通运行打印 72861972'], ['transmute 2 → bool', '普通运行打印 false;Miri 报错']], ['uninit u32'])),
    step("未对齐引用:把偏移 1 的地址当 &u32。这次连普通运行也报错:默认的调试编译带有对齐检查,panic「misaligned pointer dereference: address must be a multiple of 0x4」,退出码 -6(abort)。Miri 也报错,指出「encountered an unaligned reference (required 4 byte alignment but found 1)」。注意:这里普通运行是未加 -O 的调试构建;没有验证加 -O 后是否仍会检查。", t=tl(S(4)), mark=lidx(S(4), 'misaligned pointer', 'unaligned reference'), kv=KV([['普通运行(调试构建)', 'panic,退出码 -6'], ['Miri', '报 unaligned reference']], ['Miri'])),
    step("别名规则:从同一个裸指针先后创建 &mut r1、&mut r2,写 r2 之后再写 r1。普通运行打印 30,看起来没事。Miri 默认的 Stacked Borrows 报:r1 的标签在 4:23 创建、在 5:23 被另一次 Unique retag 作废,所以 7:5 写入时「that tag does not exist in the borrow stack」。换成 -Zmiri-tree-borrows 模型,同一段代码同样报错:r1 的状态变成 Disabled,原因是 6:5 的 *r2 = 20 这次外部写,「write access through <530> ... is forbidden」。两个模型都判这段代码是 UB。", t=tl(S(5)), mark=lidx(S(5), 'tag does not exist', 'is forbidden', 'Disabled'), done=lidx(S(5), '退出码 0', '    30'), kv=KV([['普通运行', '打印 30'], ['Stacked Borrows', 'tag 不在 borrow stack'], ['Tree Borrows', 'Disabled,写入被禁止']], ['Stacked Borrows'])),
    step("数据竞争:主线程与子线程无同步地写同一个 u32。普通运行退出码 0、打印 x = 1(碰巧「正常」);Miri 报「Data race detected between (1) non-atomic write on thread main and (2) non-atomic write on thread unnamed-1」,并给出两个写入的位置(9:18 与 11:14)以及线程是从 7:13 的 spawn 创建的。", t=tl(S(6)), mark=lidx(S(6), 'Data race detected', '(2) just happened', '(1) occurred earlier'), done=lidx(S(6), 'x = 1'), kv=KV([['普通运行', 'x = 1,退出码 0'], ['Miri', '检测出两处非原子写']], ['Miri'])),
    step("内存泄漏:mem::forget 一个 Box 和一个 Vec 后程序照常打印 done。普通运行退出码 0;Miri 在结束时报两个泄漏,「alloc292 (Rust heap, size: 16, align: 1)」与「alloc342 (Rust heap, size: 12, align: 4)」,并指出它们分配的位置(2:13、4:13),退出码 1;可用 -Zmiri-ignore-leaks 关闭这项检查。", t=tl(S(7)), mark=lidx(S(7), 'memory leaked', 'ignore-leaks'), done=lidx(S(7), 'done'), kv=KV([['泄漏', '16 字节 + 12 字节'], ['关闭检查', '-Zmiri-ignore-leaks']], ['泄漏'])),
    step(f"代价:同一个循环,每个结果都 black_box。原生 -O 在 100 万次迭代用 {sl[2][1]:.2f} ms;Miri(加 -Zmiri-disable-isolation 用真实时钟)用 {sl[2][2] / 1000:.1f} 秒,大约慢 {sl[2][2] / sl[2][1]:.0f} 倍(10 万次迭代时 {sl[1][2] / 1000:.1f} 秒)。另外注意:Miri 默认开着隔离,程序里的 Instant 是虚拟时钟,程序自己量到的是 {sl[2][3]:.0f} ms,与真实耗时不是一回事。", t=tl(S(8)), b=bars([[f'{x[0]:,} 次(Miri 真实 ms)', x[2], f'{x[2]:.0f}'] for x in sl], sl[2][2], done=[0, 1, 2]), kv=KV([['100 万次 原生 -O', f'{sl[2][1]:.2f} ms'], ['100 万次 Miri', f'{sl[2][2] / 1000:.1f} s'], ['倍数', f'≈{sl[2][2] / sl[2][1]:.0f}×']], ['倍数'])),
    step("Miri 的限制:默认隔离,TcpListener::bind 报「unsupported operation: `socket` not available when isolation is enabled」,加 -Zmiri-disable-isolation 后能运行并打印监听地址;调用外部 C 函数 ffs,Miri 报「can't call foreign function `ffs` on OS `macos`」(普通运行打印 4)。所以涉及系统调用或链接 C 库的代码,Miri 要么需要放开隔离,要么根本无法执行。", t=tl(S(9)), mark=lidx(S(9), 'not available when isolation', "can't call foreign function"), done=lidx(S(9), '127.0.0.1:'), kv=KV([['socket', '默认不支持;disable-isolation 后可运行'], ['外部 C 函数 ffs', '不支持']], ['外部 C 函数 ffs'])),
]
